"""Write the completion receipt only after both verification stages pass."""
from pathlib import Path
import json,sqlite3
BASE=Path(__file__).resolve().parents[1];DATA=BASE/'data'
f=json.loads((DATA/'foundation_verification.json').read_text())
m=json.loads((DATA/'metadata_source_verification.json').read_text())
c=json.loads((DATA/'catalog_verification.json').read_text())
if not (f['passed'] and m['passed'] and c['counts']['physical_tables']==f['total_tables']):raise RuntimeError('Foundation not fully verified')
lines=['# IPEDS data foundation','','Completed scope: faithful annual SQLite copies and a comprehensive searchable source-metadata catalog. Original Access databases, codebooks and release notes remain unchanged. Measure harmonization, analytical benchmark questions and the conversational agent are deferred until the project owner supplies validated results.','','## Where the files are','','All generated files are under this document’s neighboring `data/` folder:','','```text','agent-redesign/','    data/','        annual/','            IPEDS_2015-16_Final/IPEDS201516.sqlite','            IPEDS_2016-17_Final/IPEDS201617.sqlite','            ...','            IPEDS_2024-25_Provisional/IPEDS202425.sqlite','        metadata_catalog.sqlite','        foundation_verification.json','        metadata_source_verification.json','        catalog_verification.json','    ingestion/','        README.md','        ... repeatable import, verification and search scripts ...','```','','The new 2015–16 copy is independently generated from the designated source root; the earlier SQLite file beside the originals is not modified or relied upon.','','## Annual copies','','| Release | User tables | Rows, including metadata tables |','| --- | ---: | ---: |']
for r in f['annual_copies']:lines.append(f"| {r['release']} | {r['tables']:,} | {r['rows']:,} |")
lines+=['',f"Total: **{f['total_tables']:,} tables and {f['total_rows']:,} rows** across ten independent annual copies.",'','Each annual folder includes a source/output hash manifest, table-level verification hashes, physical column/type/null-count inventory, and conversion log. Annual data are not unioned or harmonized. Original table names, fields and values are retained. Exact decimal fields are represented as decimal text where needed to avoid precision loss; source types are preserved in the schema catalog.','','## What is in the catalog','','| Content | Imported count |','| --- | ---: |']
for title,key in [('Annual releases','releases'),('Original source files registered','source_files'),('Codebook sheets','sheets'),('Original nonempty workbook rows','sheet_rows'),('Table-definition entries','table_docs'),('Variable-definition entries','variable_docs'),('Categorical-code entries','code_values'),('Release-note paragraphs','release_notes'),('Physical tables','physical_tables'),('Physical columns','physical_columns')]:lines.append(f"| {title} | {c['counts'][key]:,} |")
lines+=['','Counts are source entries, including repeated documentation/code entries when present. They do not mean that there are that many distinct cross-year concepts. The catalog contains every sheet, including supplemental change sheets, introductions and metadata definitions. Source references retain release, file hash, sheet and row/paragraph.','','Keyword and phrase search is implemented through SQLite FTS5. A small read-only search utility is available at `ingestion/search_catalog.py`; usage and schema documentation are in `ingestion/README.md`. This is a searchable foundation, not yet an LLM agent.','','## Documentation issues are separate from source definitions','','Observed mismatches are stored in the catalog’s `issues` table, with candidate physical locations where available. Source metadata is preserved; candidates are not automatically approved mappings.','','| Issue type | Count |','| --- | ---: |']
for kind,n in c['issues_by_type'].items():lines.append(f'| {kind} | {n:,} |')
lines+=['','The known 2023–24 SFA placement conflicts are visible to search users as warnings, along with source row references. Shared UNITID fields omitted from dictionaries are informational, not treated as data corruption.','','## Verification completed','','- Original Access source hashes match before/after conversion and during final reconciliation.','- Every copied table matches its source row count.','- Every copied cell was checked through canonical row-value hashes before insertion and after SQLite read-back; null counts also match column by column.','- Each annual SQLite database passed integrity_check.','- Independent checks confirmed all output file hashes, table inventories, row counts and catalog physical schemas.','- Every imported nonempty workbook row/cell and release-note paragraph was independently compared with its original source.','- Catalog foreign keys, integrity, search-index coverage and keyword searches passed.','','These checks establish faithful storage and metadata retrieval. They do not establish that every measure is longitudinally comparable or certify any analytical answer. No validated question-bank statistics were tested in this stage.','','## Next step when the project owner is ready','','Receive the test questions, exact populations/periods and independently validated results. Then develop reviewed annual measure mappings, answer those questions from the annual copies, and compare results against the supplied benchmarks before integrating the agent.']
(BASE/'DATA_FOUNDATION.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Wrote DATA_FOUNDATION.md')
